CREATE TABLE course_wishlist(user_id UUID NOT NULL,course_id UUID NOT NULL REFERENCES courses(id) ON DELETE CASCADE,created_at TIMESTAMP NOT NULL DEFAULT NOW(),PRIMARY KEY(user_id,course_id));
CREATE TABLE course_announcements(id UUID PRIMARY KEY,course_id UUID NOT NULL REFERENCES courses(id) ON DELETE CASCADE,title VARCHAR(200) NOT NULL,content VARCHAR(10000) NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT NOW());
CREATE TABLE platform_outbox(id UUID PRIMARY KEY,topic VARCHAR(100) NOT NULL,payload TEXT NOT NULL,attempts INT NOT NULL DEFAULT 0,next_attempt_at TIMESTAMP NOT NULL DEFAULT NOW(),last_error VARCHAR(200),created_at TIMESTAMP NOT NULL DEFAULT NOW(),delivered_at TIMESTAMP);
